def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return
    n = int(input_data)

    count = 0

    # Single digit numbers: 1 to 9 (all have odd number of digits)
    if n >= 9:
        count += 9
    else:
        count += n

    # Two digit numbers: 10 to 99 (even number of digits) -> skip

    # Three digit numbers: 100 to 999 (odd number of digits)
    if n >= 100:
        start = 100
        end = min(n, 999)
        count += (end - start + 1)

    # Four digit numbers: 1000 to 9999 (even number of digits) -> skip

    # Five digit numbers: 10000 to 99999 (odd number of digits)
    if n >= 10000:
        start = 10000
        end = min(n, 99999)
        count += (end - start + 1)

    print(count)

if __name__ == "__main__":
    solve()

