def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return
    n = int(input_data)

    s_n = str(n)
    num_digits = len(s_n)

    count = 0

    # For all complete digit lengths less than num_digits that are odd
    for length in range(1, num_digits):
        if length % 2 == 1:
            count += 9 * (10 ** (length - 1))

    # For the current length (num_digits), if it is odd, include all numbers from 10^(num_digits-1) to n
    if num_digits % 2 == 1:
        count += n - (10 ** (num_digits - 1)) + 1

    print(count)

