def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)

    s_N = str(N)
    L = len(s_N)

    if L % 2 == 1:
        # Full ranges for lengths 1, 3, ..., L-2 are completely included
        # Number of integers with odd length < L
        count = 0
        for length in range(1, L, 2):
            if length == 1:
                count += 9
            else:
                count += 9 * 10 ** (length - 1)
        # For length L (which is odd), include numbers from 10^(L-1) to N
        start = 10 ** (L - 1)
        count += (N - start + 1)
    else:
        # Length L is even, so we only count full ranges for odd lengths < L
        count = 0
        for length in range(1, L, 2):
            if length == 1:
                count += 9
            else:
                count += 9 * 10 ** (length - 1)

    print(count)

